export function createDocumentServiceClient({fetchImpl=(...args)=>fetch(...args),isCurrent=()=>true}={}){
 const controllers=new Set();let disposed=false;
 return {async request(path,body,{timeout=30000}={}){if(disposed||!isCurrent())throw new DOMException('页面已关闭','AbortError');const controller=new AbortController();controllers.add(controller);let timedOut=false;const timer=setTimeout(()=>{timedOut=true;controller.abort();},timeout);try{const response=await fetchImpl('/api'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',redirect:'error',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});const data=await response.json().catch(()=>({}));if(disposed||!isCurrent())throw new DOMException('页面已关闭','AbortError');if(!response.ok){const message=typeof data.error==='string'?data.error:typeof data.error?.message==='string'?data.error.message:'服务暂时不可用，请稍后重试。';throw Object.assign(new Error(message),{status:response.status});}return data;}catch(error){if(timedOut)throw Error('请求等待超时，请先刷新任务状态再重试，避免重复提交。');throw error;}finally{clearTimeout(timer);controllers.delete(controller);}},dispose(){disposed=true;controllers.forEach(controller=>controller.abort());controllers.clear();}};
}
export function watchDocumentService(container,dispose){const dialog=container.closest('dialog');const observer=new container.ownerDocument.defaultView.MutationObserver(()=>{if(!container.isConnected||dialog&&!dialog.open)dispose();});observer.observe(container.ownerDocument.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open']});dialog?.addEventListener('close',dispose,{once:true});return ()=>{observer.disconnect();dialog?.removeEventListener('close',dispose);};}
export async function fileBase64(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(binary);}
export const documentServiceLoginHref=()=>'/auth.html?mode=login&next='+encodeURIComponent('/workspace.html'+location.search+location.hash);
